const out = [];
for (const it of $input.all()) {
  const p = it.json || {};
  const raw = String(p.output || '').trim();
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  const base = $('Normalize Report').first().json || {};
  const severity = String(parsed.severity || 'normal').toLowerCase();
  out.push(Object.assign({}, base, {
    severity: severity,
    summary: String(parsed.summary || '').trim() || raw.slice(0, 200),
    suggested_action: String(parsed.suggested_action || '').trim(),
    is_urgent: severity === 'urgent' ? 'yes' : 'no',
    ai_raw: raw.slice(0, 400)
  }));
}
return out;

const rows = ($input.all() || []).map(r => (r.json || {})).filter(r => r && String(r.report_id || '').trim());
const now = new Date();
const cutoff = new Date(now.getTime() - 24 * 3600 * 1000);
const fresh = rows.filter(r => {
  if (!r.reported_at) { return false; }
  const d = new Date(r.reported_at);
  return !isNaN(d.getTime()) && d >= cutoff && d <= now;
}).sort((a, b) => new Date(a.reported_at) - new Date(b.reported_at));
if (fresh.length === 0) { return []; }
const office = (fresh[0] && fresh[0].supervisor_email) || 'user@example.com';
const dateLabel = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Pontianak', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
const lines = fresh.map(r => {
  const t = new Date(r.reported_at);
  const ts = !isNaN(t.getTime()) ? t.toLocaleString('en-GB', { timeZone: 'Asia/Pontianak', hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit', year: 'numeric' }) : (r.reported_at || '');
  return '- ' + ts + ' | ' + r.site + ' | ' + r.officer_name + ' | ' + r.report_type + ' | ' + (r.severity || 'normal') + (r.summary ? ' | ' + r.summary : '');
});
const hasUrgent = fresh.some(r => String(r.is_urgent || '') === 'yes');
const subject = hasUrgent ? 'DAILY ACTIVITY REPORT - ' + dateLabel + ' (INCLUDES URGENT ITEM)' : 'Daily activity report - ' + dateLabel;
const body = [subject, '', ...lines, '', 'End of report.'].join(String.fromCharCode(10));
return [{ json: { supervisor_email: office, dar_subject: subject, dar_body: body, report_count: fresh.length } }];

const rows = ($input.all() || []).map(r => (r.json || {})).filter(r => r && String(r.report_id || '').trim());
const now = new Date();
const cutoff = new Date(now.getTime() - 30 * 24 * 3600 * 1000);
const month = rows.filter(r => {
  const d = new Date(r.reported_at || '');
  return !isNaN(d.getTime()) && d >= cutoff && d <= now;
});
if (month.length === 0) { return []; }
const total = month.length;
const incidents = month.filter(r => String(r.report_type || '').toLowerCase().includes('incident')).length;
const urgent = month.filter(r => String(r.is_urgent || '') === 'yes').length;
const bySite = {};
for (const r of month) {
  const s = String(r.site || 'Unknown');
  bySite[s] = (bySite[s] || 0) + 1;
}
const siteList = Object.entries(bySite).map(([site, count]) => site + ': ' + count).join('; ');
const office = (month[0] && month[0].supervisor_email) || 'user@example.com';
const monthLabel = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Pontianak', year: 'numeric', month: '2-digit' }).format(now);
const itemsJson = JSON.stringify(month.map(r => ({ t: r.reported_at, s: r.site, o: r.officer_name, ty: r.report_type, sev: r.severity || 'normal', sum: r.summary || '' })));
return [{ json: {
  supervisor_email: office,
  month_label: monthLabel,
  total_reports: total,
  incident_count: incidents,
  urgent_count: urgent,
  sites_json: siteList,
  rows_json: itemsJson
} }];

const out = [];
for (const it of $input.all()) {
  const p = it.json || {};
  const raw = String(p.output || '').trim();
  let parsed = {};
  try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
  const base = $('Collate Month Stats').first().json || {};
  out.push(Object.assign({}, base, {
    monthly_subject: parsed.subject || ('Monthly security review ' + base.month_label),
    monthly_body: parsed.body || raw
  }));
}
return out;
